def backtrack(idx, labels, used_labels, used_diffs, depth):
    if depth > 100000:
        return None

    if idx == n_vertices:
        return labels[:]

    # Try labels in random order
    available = [l for l in range(28) if l not in used_labels]
    random.shuffle(available)

    for label in available:
        # Check if this label is valid
        valid = True
        for v in range(idx):
            if labels[v] is not None:
                # Check if there's an edge between v and idx
                if (v, idx) in edges or (idx, v) in edges:
                    diff = abs(label - labels[v])
                    if diff in used_diffs:
                        valid = False
                        break

        if valid:
            labels[idx] = label
            used_labels.add(label)
            new_diffs = set()
