                if labels[v] is not None:
                    if (v, idx) in edges or (idx, v) in edges:
                        diff = abs(label - labels[v])
                        new_diffs.add(diff)
                        used_diffs.add(diff)

            result = backtrack(idx + 1, labels, used_labels, used_diffs, depth + 1)
            if result is not None:
                return result

            # Backtrack
            labels[idx] = None
            used_labels.remove(label)
            for d in new_diffs:
                used_diffs.remove(d)

